"""Lay students out in rows of seats, ordered by surname."""

from typing import List


def _name_key(student):
    last = student.last_name.lower()
    first = student.first_name.lower()
    return (last, first, student.student_id)


def _row_line(index, chunk):
    names = " | ".join(item.display_name for item in chunk)
    return f"Row {index}: {names}"


def _chunks(items, size):
    spans = range(0, len(items), size)
    return [items[head:head + size] for head in spans]


def _check(students, seats):
    if seats < 1:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")


# ---
def seat_rows(students, seats: int) -> List[str]:
    """One text line per row, sorted by last name."""
    _check(students, seats)
    rows = _chunks(sorted(students, key=_name_key), seats)
    pairs = enumerate(rows, 1)
    return [_row_line(index, row) for index, row in pairs]

