# owner: platform
import unittest
from rosterkit.seating import seat_rows
from rosterkit.models import Student


def pupil(last, first, ident="1"):
    return Student(ident, last, first, "A")


class SeatRowTests(unittest.TestCase):
    def setUp(self):
        self.group = [
            pupil("Halloway", "Juno", "2"),
            pupil("Dunmere", "Piet", "1"),
            pupil("Avery", "Cole", "3")
        ]

    def test_sorted_and_split_into_rows(self):
        lines = seat_rows(self.group, 2)
        self.assertEqual(lines, [
            "Row 1: Avery, Cole | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    def test_single_row_when_seats_exceed_students(self):
        lines = seat_rows(self.group, 10)
        self.assertEqual(len(lines), 1)
        self.assertTrue(lines[0].startswith("Row 1: Avery"))

    def test_same_surname_falls_back_to_first_name(self):
        pair = [pupil("Lee", "Zed", "1")]
        pair.append(pupil("Lee", "Amy", "2"))
        expected = ["Row 1: Lee, Amy | Lee, Zed"]
        self.assertEqual(seat_rows(pair, 2), expected)

    def test_input_list_is_not_reordered(self):
        before = list(self.group)
        seat_rows(self.group, 2)
        self.assertEqual(self.group, before)

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.group, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.group, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
